# Unrecognized query keys (including ad-platform click IDs) are discarded.
for field in CLICK_ID_FIELDS:
    values = parsed.get(field, [""])
    if len(values) != 1:
        raise InputError("duplicate_click_id")
    value = string(values[0], 1024, "invalid_click_id")
    if value and not re.fullmatch(r"[A-Za-z0-9_.~-]+", value):
        raise InputError("invalid_click_id")
    utms[field] = value
# Only the five UTMs and supported click IDs are retained.
